(function(){var h="<!-- Black Optix Tint Charlotte \u2014 $199 page BOTTOM BLOCK \u00b7 10/15/26 (test 4, Nam's picks): \"What $199 gets you\" (sedan, four checks, windshield + sunroof not included, no extras)\n + \"Worth the drive\": drawn map of the towns around the shop, the line names the VISITOR's town with the no-traffic minutes (fastest route, driver doing 15 over = Google's no-traffic time minus ~15%).\n Town from a free IP lookup (geojs, then ipwho), never stored. No phone anywhere on this page (Meta traffic, calls cannot be tracked). -->\n<link href=\"https://fonts.googleapis.com/css2?family=Barlow+Condensed:ital,wght@1,800&family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<div id=\"bot-bottom\" class=\"th-yellow\">\n<style>\n  #bot-bottom{display:block;width:100%;max-width:100%;--card:#151515;--card2:#1E1E1E;--line:#2A2A2A;--txt:#fff;--mute:#A6A6A6;--acc:#FFC81C;box-sizing:border-box;font-family:\"Inter\",system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;color:var(--txt);margin:0 auto;padding:6px 0 4px;text-align:left}\n  #bot-bottom *{box-sizing:border-box;font-family:inherit}\n  #bot-bottom .bb-h{font:italic 800 clamp(26px,7vw,34px)/1 \"Barlow Condensed\",Impact,sans-serif;text-transform:uppercase;letter-spacing:.3px;margin:0 0 6px;color:#fff!important}#bot-bottom .bb-h span{color:#FFC81C!important;font:inherit}\n  #bot-bottom .bb-sub{color:var(--mute);font-size:12.5px;line-height:1.45;margin:0 0 10px}\n  .bb-list{background:var(--card);border:1px solid var(--line);border-radius:14px;overflow:hidden}\n  .bb-row{display:flex;align-items:center;gap:10px;padding:11px 14px;border-bottom:1px solid var(--line)}.bb-row:last-child{border:0}\n  .bb-row b{display:block;font-size:13.5px;font-weight:700;line-height:1.2;color:var(--txt)}.bb-row small{display:block;font-size:11px;font-weight:500;line-height:1.3;color:var(--mute);margin-top:2px}\n  .bb-ck{width:18px;height:18px;border-radius:50%;background:#1f3b27;color:#7ee2a0;font-size:11px;font-weight:800;line-height:18px;text-align:center;flex-shrink:0}\n  .bb-map{margin-top:18px;background:var(--card);border:1px solid var(--line);border-radius:16px;overflow:hidden}\n  .bb-mrow{display:grid;grid-template-columns:1fr}@media (min-width:900px){.bb-mrow{grid-template-columns:1.1fr 1fr;align-items:stretch}.bb-svg{aspect-ratio:auto;min-height:380px}.bb-side{padding:28px;display:flex;flex-direction:column;justify-content:center}#bot-bottom .bb-big{font-size:30px}}\n  .bb-svg{position:relative;aspect-ratio:1/0.92;background:#0f1113}.bb-svg svg{position:absolute;inset:0;width:100%;height:100%}\n  .bb-side{padding:14px 14px 16px}\n  #bot-bottom .bb-big{font:italic 800 22px/1.05 \"Barlow Condensed\",Impact,sans-serif;text-transform:uppercase;color:#fff!important}#bot-bottom .bb-big span{color:#FFC81C!important;font:inherit}\n  .bb-side p{font-size:13px;font-weight:500;line-height:1.5;color:#d6d6d6;margin:8px 0 0}.bb-side p b{color:var(--txt)}\n  .bb-go{display:block;margin-top:12px;background:var(--acc);color:#111!important;text-align:center;border-radius:999px;padding:12px;font-size:14px;font-weight:800;line-height:1;text-decoration:none!important;box-shadow:0 0 22px rgba(255,200,28,.3);position:relative;overflow:hidden;animation:bbJump 3.4s ease-in-out infinite}   /* 10/15 Nam: it blended in = shine sweep + a little jump */\n  .bb-go::after{content:\"\";position:absolute;top:-40%;bottom:-40%;left:-60%;width:40%;background:linear-gradient(100deg,rgba(255,255,255,0) 0,rgba(255,255,255,.55) 50%,rgba(255,255,255,0) 100%);transform:skewX(-20deg);animation:bbShine 3.4s ease-in-out infinite}\n  @keyframes bbShine{0%,55%{left:-60%}85%,100%{left:130%}}\n  @keyframes bbJump{0%,60%,100%{transform:translateY(0)}68%{transform:translateY(-7px)}76%{transform:translateY(0)}82%{transform:translateY(-3px)}88%{transform:translateY(0)}}\n  @media (prefers-reduced-motion:reduce){.bb-go,.bb-go::after{animation:none!important}}\n  .bb-lab{font-size:10.5px;font-weight:800;letter-spacing:.8px;text-transform:uppercase;color:var(--mute);margin:14px 0 7px}   /* 10/15 Nam: the four \"Just tinted\" cars moved down here so the left column runs as tall as the map on desktop */\n  .bb-cars{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.bb-cars div{aspect-ratio:4/3;border-radius:10px;background:#222 center/cover;position:relative;overflow:hidden}.bb-cars div span{position:absolute;left:0;right:0;bottom:0;padding:16px 7px 6px;font-size:10.5px;font-weight:600;color:#eee;background:linear-gradient(transparent,rgba(0,0,0,.8))}\n  @media (min-width:900px){.bb-cars{grid-template-columns:repeat(4,1fr)}.bb-cars div{aspect-ratio:1/0.85}}\n  @media (min-width:900px){#bot-bottom .bb-two{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}#bot-bottom .bb-map{margin-top:0}}\n<\/style>\n  <div class=\"bb-two\">\n    <div>\n      <div class=\"bb-h\">What <span>$199 gets you<\/span><\/div>\n      <div class=\"bb-sub\">The $199 special is for a sedan or coupe. SUVs and trucks: the price shows after you tap your car.<\/div>\n      <div class=\"bb-list\">\n        <div class=\"bb-row\"><span class=\"bb-ck\">\u2713<\/span><div><b>All side windows + rear glass<\/b><small>Windshield and sunroof not included.<\/small><\/div><\/div>\n        <div class=\"bb-row\"><span class=\"bb-ck\">\u2713<\/span><div><b>Optix Excel hybrid film<\/b><small>Made in the USA. Blocks heat and 99% of UV.<\/small><\/div><\/div>\n        <div class=\"bb-row\"><span class=\"bb-ck\">\u2713<\/span><div><b>Lifetime warranty<\/b><small>No bubbling, no purple, no peeling.<\/small><\/div><\/div>\n        <div class=\"bb-row\"><span class=\"bb-ck\">\u2713<\/span><div><b>Done in 2 to 3 hours<\/b><small>Wait in the lounge or drop it off before 2pm.<\/small><\/div><\/div>\n      <\/div>\n      <div class=\"bb-lab\">Just tinted<\/div>\n      <div class=\"bb-cars\"><div style=\"background-image:url(https://images.leadconnectorhq.com/image/f_webp/q_80/r_800/u_https://assets.cdn.filesafe.space/GNwzvxwLa2XVth9Isr0Z/media/ffb19cc6-89a6-480a-a6f9-85a823358b6f.jpeg)\"><span>Dodge Charger<\/span><\/div><div style=\"background-image:url(https://images.leadconnectorhq.com/image/f_webp/q_80/r_800/u_https://assets.cdn.filesafe.space/GNwzvxwLa2XVth9Isr0Z/media/6c70fb83-7304-4d96-a521-ca7cb738257e.webp)\"><span>Ford Mustang<\/span><\/div><div style=\"background-image:url(https://images.leadconnectorhq.com/image/f_webp/q_80/r_800/u_https://assets.cdn.filesafe.space/GNwzvxwLa2XVth9Isr0Z/media/3be7f268-df02-4d16-a08c-0827008543c6.jpeg)\"><span>Chevy Camaro<\/span><\/div><div style=\"background-image:url(https://images.leadconnectorhq.com/image/f_webp/q_80/r_800/u_https://assets.cdn.filesafe.space/GNwzvxwLa2XVth9Isr0Z/media/b2e0914b-2bef-401a-9364-61728962a105.webp)\"><span>Mercedes G-Class<\/span><\/div><\/div>\n    <\/div>\n    <div>\n      <div class=\"bb-h\" style=\"margin-top:18px\" id=\"bb-driveh\">Worth <span>the drive<\/span><\/div>\n      <div class=\"bb-map\"><div class=\"bb-mrow\">\n        <div class=\"bb-svg\"><svg viewBox=\"0 0 400 368\" id=\"bb-svg\" aria-label=\"Map of the towns around Charlotte with drive times to the shop\"><\/svg><\/div>\n        <div class=\"bb-side\">\n          <div class=\"bb-big\" id=\"bb-big\"><span>15 minutes<\/span> from most of Charlotte<\/div>\n          <p>2725 Westinghouse Blvd #300, Steele Creek, right off I-485 and I-77. Drive in, wait in the lounge, drive out tinted.<\/p>\n          <p id=\"bb-line\"><b>From Fort Mill or Rock Hill?<\/b> Same $199, 15 to 20 minutes up I-77.<\/p>\n          <a class=\"bb-go\" href=\"#wm-book\">Pick my day \u2191<\/a>\n        <\/div>\n      <\/div><\/div>\n    <\/div>\n  <\/div>\n  <script>(function(){ var r=document.getElementById(\"bot-bottom\"); if(!r)return; var e=r.parentElement, n=0; while(e&&e!==document.body&&n<6){ if(/^custom-code-/.test(e.id||\"\")){ e.style.setProperty(\"width\",\"100%\",\"important\"); e.style.setProperty(\"max-width\",\"100%\",\"important\"); } e=e.parentElement; n++; }\n    if(document.querySelector(\"#bot-bottom .bb-h\")) { var h=r.querySelector(\"#bb-driveh\"); if(matchMedia(\"(min-width:900px)\").matches) h.style.marginTop=\"0\"; }\n    /* towns: [name, lat, lon, minutes]. Minutes = OSRM no-traffic drive from the shop, minus 15% (Nam 10/15: \"no traffic, 15 over\"), rounded to 5. */\n    var SHOP=[35.131,-80.951], T=[[\"Uptown\",35.227,-80.843,15],[\"SouthPark\",35.152,-80.832,15],[\"Ballantyne\",35.052,-80.848,10],[\"Pineville\",35.083,-80.892,10],[\"Matthews\",35.117,-80.724,20],[\"Mint Hill\",35.180,-80.648,30],[\"Fort Mill\",35.007,-80.945,15],[\"Rock Hill\",34.925,-81.025,20],[\"Gastonia\",35.262,-81.187,30],[\"Belmont\",35.243,-81.037,20],[\"Huntersville\",35.411,-80.843,30],[\"Concord\",35.409,-80.580,45],[\"Indian Trail\",35.077,-80.669,25],[\"Mooresville\",35.585,-80.810,45],[\"Monroe\",34.985,-80.549,35],[\"Tega Cay\",35.024,-81.028,20],[\"Waxhaw\",34.925,-80.743,30],[\"Cornelius\",35.487,-80.860,35],[\"Kannapolis\",35.487,-80.622,45],[\"Mount Holly\",35.298,-81.016,20],[\"Weddington\",35.022,-80.761,20],[\"Lake Wylie\",35.110,-81.043,15],[\"Harrisburg\",35.324,-80.657,35],[\"Davidson\",35.499,-80.849,35],[\"Clover\",35.111,-81.226,25],[\"York\",34.994,-81.242,30],[\"Stallings\",35.090,-80.686,20],[\"Steele Creek\",35.120,-80.980,5]];\n    var ON=[\"Uptown\",\"SouthPark\",\"Ballantyne\",\"Pineville\",\"Matthews\",\"Mint Hill\",\"Fort Mill\",\"Rock Hill\",\"Gastonia\",\"Belmont\",\"Huntersville\",\"Concord\",\"Indian Trail\",\"Mooresville\",\"Monroe\"];   /* the ones drawn; the rest only feed the line */\n    var W=400,H=368,lon0=-81.40,lon1=-80.36,lat0=35.66,lat1=34.86, X=function(lo){return (lo-lon0)/(lon1-lon0)*W}, Y=function(la){return (lat0-la)/(lat0-lat1)*H};\n    var s='<defs><radialGradient id=\"bbg\" cx=\".5\" cy=\".5\" r=\".5\"><stop offset=\"0\" stop-color=\"#FFC81C\" stop-opacity=\".32\"/><stop offset=\".6\" stop-color=\"#FFC81C\" stop-opacity=\".08\"/><stop offset=\"1\" stop-color=\"#FFC81C\" stop-opacity=\"0\"/><\/radialGradient><\/defs><rect width=\"400\" height=\"368\" fill=\"#0f1113\"/>';\n    var hx=X(SHOP[1]), hy=Y(SHOP[0]); s+='<ellipse cx=\"'+(hx+15)+'\" cy=\"'+(hy-15)+'\" rx=\"175\" ry=\"165\" fill=\"url(#bbg)\"/>';\n    var lab={\"Pineville\":[-8,\"end\"],\"Fort Mill\":[-8,\"end\"],\"Rock Hill\":[-8,\"end\"],\"Belmont\":[-8,\"end\"],\"Huntersville\":[-8,\"end\"],\"Monroe\":[-8,\"end\"]};\n    s+='<circle cx=\"'+hx+'\" cy=\"'+hy+'\" r=\"13\" fill=\"#FFC81C\" fill-opacity=\".25\"/><circle cx=\"'+hx+'\" cy=\"'+hy+'\" r=\"6\" fill=\"#FFC81C\"/><text x=\"'+(hx-11)+'\" y=\"'+(hy+4)+'\" text-anchor=\"end\" font-size=\"10.5\" fill=\"#FFC81C\" font-family=\"Inter,sans-serif\" font-weight=\"800\">Black Optix \u00b7 Steele Creek<\/text>';\n    T.forEach(function(c){ if(ON.indexOf(c[0])<0)return; var x=+X(c[2]).toFixed(1), y=+Y(c[1]).toFixed(1), L=lab[c[0]]||[8,\"start\"];\n      s+='<circle cx=\"'+x+'\" cy=\"'+y+'\" r=\"3.2\" fill=\"#fff\"/><text x=\"'+(x+L[0])+'\" y=\"'+(y+3.5)+'\" font-size=\"9\" fill=\"#ddd\" font-family=\"Inter,sans-serif\" font-weight=\"600\" text-anchor=\"'+L[1]+'\">'+c[0]+' <tspan fill=\"#FFC81C\" font-weight=\"800\">'+c[3]+' min<\/tspan><\/text>'; });\n    document.getElementById(\"bb-svg\").innerHTML=s;\n    /* the visitor's town: free IP lookup, NC/SC only; a known town prints its minutes, Charlotte itself keeps \"most of Charlotte\" */\n    var byName={}; T.forEach(function(c){ byName[c[0].toLowerCase()]=c; }); var alias={\"charlotte\":null,\"fort mill\":\"fort mill\",\"tega cay\":\"tega cay\",\"rock hill\":\"rock hill\",\"indian trail\":\"indian trail\",\"mint hill\":\"mint hill\",\"lake wylie\":\"lake wylie\",\"mount holly\":\"mount holly\",\"steele creek\":\"steele creek\"};\n    function show(town,min){ try{ var big=document.getElementById(\"bb-big\"), line=document.getElementById(\"bb-line\"); if(town&&min){ big.innerHTML='About <span>'+min+' minutes<\/span> from '+town; line.innerHTML='<b>No traffic, no fuss.<\/b> '+min+' minutes door to door, then 2 to 3 hours in the shop and you drive home tinted.'; window.dataLayer=window.dataLayer||[]; window.dataLayer.push({event:\"ib_drive_town\",town:town}); } }catch(e){} }\n    function accept(city,region){ var k=String(city||\"\").toLowerCase().trim(); var rg=String(region||\"\").toLowerCase(); if(rg&&!/north carolina|south carolina|^nc$|^sc$/.test(rg))return null; if(k===\"charlotte\")return null; var c=byName[alias[k]||k]; return c||null; }\n    var srcs=[\"https://get.geojs.io/v1/ip/geo.json\",\"https://ipwho.is/\"], i=0;\n    function tryNext(){ if(i>=srcs.length)return; var u=srcs[i++], done=false; var t=setTimeout(function(){ done=true; tryNext(); },2500);\n      fetch(u,{mode:\"cors\"}).then(function(x){return x.json()}).then(function(j){ if(done)return; done=true; clearTimeout(t); var c=accept(j.city,j.region||j.region_name||j.region_code); if(c) show(c[0],c[3]); else if(!j.city) tryNext(); }).catch(function(){ if(done)return; done=true; clearTimeout(t); tryNext(); }); }\n    try{ tryNext(); }catch(e){}\n    var go=r.querySelector(\".bb-go\"); if(go) go.addEventListener(\"click\",function(e){ var f=document.getElementById(\"wm-book\"); if(f){ e.preventDefault(); f.scrollIntoView({behavior:\"smooth\",block:\"start\"}); } }); })();<\/script>\n<\/div>\n";var s=document.currentScript;if(!s||!s.parentNode)return;var d=document.createElement('div');d.innerHTML=h;var scripts=[];d.querySelectorAll('script').forEach(function(x){scripts.push(x.textContent);x.remove();});
while(d.firstChild){s.parentNode.insertBefore(d.firstChild,s);}scripts.forEach(function(code){var t=document.createElement('script');t.textContent=code;document.body.appendChild(t);});})();
